import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import { useIntl } from 'react-intl';
import styled, { CSSObject } from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { DateSelector } from './DateSelector.js';
import { useDateTimePicker } from './hooks/useDateTimePicker.js';
import type {
  DateTimePickerType,
  DateTimePickerRef,
  DateTimePickerProps,
  DateSelectorRef,
} from './types.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Hint } from '../forms-core/components/hint/Hint.js';
import { _SpinButtonGroup as SpinButtonGroup } from '../spin-buttons/spin-button-group/SpinButtonGroup.js';

//#region Styling
const StyledDateTimePicker = styled.span(() => ({
  display: 'inline-flex',
  gap: Spacings.Size2,
  alignItems: 'stretch',
}));

const StyledSpinButtonGroup = styled(SpinButtonGroup)<{
  $error?: boolean;
  $disabled?: boolean;
  $type?: DateTimePickerType;
  $focusStyle?: CSSFocusStylesObject;
}>(({ $error, $disabled, $focusStyle, $type: type }) => {
  const color = $disabled
    ? $error
      ? Colors.Text.Critical.Disabled
      : Colors.Text.Neutral.Disabled
    : $error
    ? Colors.Text.Critical.Default
    : undefined;

  const backgroundColor = $disabled
    ? $error
      ? Colors.Background.Field.Critical.Disabled
      : Colors.Background.Field.Neutral.Disabled
    : $error
    ? Colors.Background.Field.Critical.Emphasized
    : Colors.Background.Field.Neutral.Emphasized;

  const animationStyle: CSSObject = {
    transitionTimingFunction: Animations.FadeOut.Easing,
    transitionDuration: Animations.FadeOut.Duration.Base,
    transitionProperty: 'color, background-color, transform',
  };

  const interactionStyles: CSSObject = {
    '&:hover': {
      backgroundColor: $disabled
        ? undefined
        : $error
        ? Colors.Background.Field.Critical.DefaultHover
        : Colors.Background.Field.Neutral.DefaultHover,
    },
  };
  const textStyle = getTextStyle('base');

  return {
    ...$focusStyle,
    ...animationStyle,
    ...interactionStyles,
    ...textStyle,

    cursor: $disabled ? 'not-allowed' : undefined,
    color,
    backgroundColor,
    '& > *': { ...animationStyle, color },

    paddingInline: Spacings.Size12,
    paddingBlock: Spacings.Size6,
    borderRadius: Borders.Radius.Field.Default,
    borderStartEndRadius: type === 'time' ? Borders.Radius.Field.Default : 0,
    borderEndEndRadius: type === 'time' ? Borders.Radius.Field.Default : 0,

    '& *::selection': {
      color: Colors.Text.OnAccent.Default,
      backgroundColor: $error
        ? Colors.Background.Field.Critical.Accent
        : Colors.Background.Field.Neutral.Accent,
    },
  };
});

const StyledDateSelector = styled(DateSelector)<{
  $error?: boolean;
  $disabled?: boolean;
  $focusStyle?: CSSFocusStylesObject;
}>(({ $error, $disabled, $focusStyle }) => ({
  ...$focusStyle,
  color: $disabled
    ? $error
      ? Colors.Text.Critical.Disabled
      : Colors.Text.Neutral.Disabled
    : $error
    ? Colors.Text.Critical.Default
    : Colors.Text.Neutral.Default,

  backgroundColor: $disabled
    ? $error
      ? Colors.Background.Field.Critical.Disabled
      : Colors.Background.Field.Neutral.Disabled
    : $error
    ? Colors.Background.Field.Critical.Emphasized
    : Colors.Background.Field.Neutral.Emphasized,

  padding: Spacings.Size6,
  borderRadius: 0,
  borderStartEndRadius: Borders.Radius.Field.Default,
  borderEndEndRadius: Borders.Radius.Field.Default,
}));

//#endregion

/**
 * Component to comfortably enter a date time value.
 * The value can be entered in the configured locale and timezone.
 * It provides the date as an ISO8601 datetime string shifted to the UTC timezone.
 */
export const DateTimePicker = forwardRef<
  DateTimePickerRef,
  DateTimePickerProps
>((props, forwardedRef) => {
  const {
    disabled,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    readonly,
  }: DateTimePickerProps = props;
  const {
    isoDateTime,
    spinButtons,
    dateSelectorProps,
    error,
    hasFormError,
    hint,
    applyDateTime,
  } = useDateTimePicker(props);

  // Form control state support to show a error hint if necessary

  const inputRef = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLSpanElement>(null);
  const dateSelectorRef = useRef<DateSelectorRef>(null);

  // No need to show the calendar widget if only a time value can be entered.
  const showDateSelector = props.type !== 'time';

  const { focusStyles } = useFocusRing({
    focusWithin: true,
    variant: error ? 'critical' : 'neutral',
  });

  const intl = useIntl();
  const calendarTriggerLabel = intl.formatMessage({
    defaultMessage: 'Datepicker calendar trigger',
    id: 'Uuc6xAAPyctyHamM',
    description: 'Text shown for the datetimepicker calendar trigger.',
  });

  // Provide root and input element reference and functions to interact with the calendar overlay
  useImperativeHandle(
    forwardedRef,
    () => ({
      element: rootRef,
      input: inputRef,
      show: () => dateSelectorRef.current?.open(),
      hide: () => dateSelectorRef.current?.close(),
      open: () => dateSelectorRef.current?.open(),
      close: () => dateSelectorRef.current?.close(),
      focus() {
        inputRef.current?.focus();
      },
    }),
    [],
  );

  // Push the iso date string into the hidden input field on change.
  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.value = isoDateTime ?? '';
    }
  }, [isoDateTime]);

  return (
    <Flex
      data-testid={dataTestId}
      flexDirection="column"
      as="span"
      style={{ display: 'inline-flex', ...consumerStyle }}
      ref={rootRef}
      gap={4}
      className={consumerClassName}
    >
      <StyledDateTimePicker
        onPasteCapture={(e) => {
          if (readonly) {
            return;
          }
          const data = e.clipboardData.getData('text/plain');
          if (applyDateTime(data)) {
            e.preventDefault();
          }
        }}
        onCopyCapture={() => {
          navigator.clipboard.writeText(isoDateTime ?? '');
        }}
      >
        <input
          ref={inputRef}
          type="hidden"
          name={props.name}
          readOnly
          defaultValue={isoDateTime ?? ''}
          size={25}
        />
        <StyledSpinButtonGroup
          valueOverflow
          $focusStyle={focusStyles}
          $type={props.type}
          $error={error}
          $disabled={disabled}
        >
          {spinButtons}
        </StyledSpinButtonGroup>
        {showDateSelector && (
          <StyledDateSelector
            ref={dateSelectorRef}
            {...dateSelectorProps}
            aria-label={calendarTriggerLabel}
            $focusStyle={focusStyles}
            $disabled={disabled}
            error={error}
            $error={error}
          />
        )}
      </StyledDateTimePicker>
      <Hint hasError={hasFormError} disabled={disabled}>
        {hint}
      </Hint>
    </Flex>
  );
});

(
  DateTimePicker as typeof DateTimePicker & { displayName: string }
).displayName = 'DateTimePicker';
